def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    total_cc = 0
    total_cd = 0
    total_dc = 0
    total_dd = 0

    for me, opp in history:
        if opp == 'C':
            opp_c += 1
        if me == 'C':
            if opp == 'C':
                total_cc += 1
            else:
                total_cd += 1
        else:
            if opp == 'C':
                total_dc += 1
            else:
                total_dd += 1

    if opp_c == 0:
        return 'D'
    opp_d = n - opp_c

    recent = history[-10:]
    recent_len = len(recent)

    recent_opp_c = 0
    recent_cc = 0
    recent_cd = 0
    recent_dc = 0
    recent_dd = 0

    for me, opp in recent:
        if opp == 'C':
            recent_opp_c += 1
        if me == 'C':
            if opp == 'C':
                recent_cc += 1
            else:
                recent_cd += 1
        else:
            if opp == 'C':
                recent_dc += 1
            else:
                recent_dd += 1

    recent_opp_d = recent_len - recent_opp_c

    # Persistent defector detection: mostly recent D and not merely retaliating.
    if n >= 8:
        if recent_opp_c <= 2 and opp_d * 2 >= opp_c:
            return 'D'
        if n >= 20 and opp_c <= n // 4 and recent_opp_c <= 3:
            return 'D'

    # Detect an anti-correlated / alternating pattern: little mutual agreement,
    # many unilateral outcomes. Stay in D against such players.
    if recent_len >= 8 and recent_cc + recent_dd <= 2 and recent_cd + recent_dc >= 6:
        return 'D'
    if n >= 12 and total_cc + total_dd <= 2 and total_cd + total_dc >= 8:
        return 'D'

    last_me, last_op = history[-1]

    if last_op == 'D':
        # If opponent's defection is the delayed response to our previous defection,
        # cooperate again to restore mutual cooperation.
        if n >= 2:
            prev_me, prev_op = history[-2]
            if prev_me == 'D' and prev_op == 'C':
                if opp_c * 2 >= n or recent_opp_c >= (recent_len + 1) // 2:
                    return 'C'
                return 'D'

        # Opponent defected while we cooperated, not as delayed punishment.
        if last_me == 'C':
            # Forgive only the first isolated lapse by a highly cooperative opponent.
            if opp_d == 1 and n >= 10 and opp_c * 10 >= n * 8:
                return 'C'
            return 'D'

        # Mutual defection: repair if the opponent has meaningful cooperation,
        # otherwise continue punishing.
        if recent_opp_c >= 3 or opp_c * 2 >= n:
            return 'C'
        return 'D'

    # Opponent cooperated.
    if last_me == 'D':
        # We just defected. Restore cooperation if the opponent is largely cooperative.
        if opp_c * 2 >= n and recent_opp_c >= (recent_len + 1) // 2:
            return 'C'
        return 'D'

    # Both cooperated last round: preserve mutual cooperation unless the opponent
    # has been clearly uncooperative overall.
    if recent_opp_c >= 4 or opp_c * 2 >= n:
        return 'C'
    return 'D'
